CREATE COLUMN TABLE "TEST_AP"."CLG1" ("ClgCode" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "Date" LONGDATE CS_LONGDATE, "Location" NVARCHAR(254), "Latitude" NVARCHAR(13), "Longitude" NVARCHAR(14), "Time" INTEGER CS_INT, "OwnerUser" SMALLINT CS_INT, "OwnerEmp" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("ClgCode", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE 